    toolkit.plugins.CPFInputField = Ext.extend(
        Ext.form.TextField,
        {
            constructor: function(cf) {
                cf.validateOnBlur = true;
                cf.validationEvent = false;
                toolkit.plugins.CPFInputField.superclass.constructor.call(this, cf);
            },

            validate: function() {
                var result = false;

                var value = this.clean(this.el.dom.value);

                if (value == "" && this.allowBlank)
                    return true;

                var notValids = [
                    '00000000000',
                    '11111111111',
                    '22222222222',
                    '33333333333',
                    '44444444444',
                    '55555555555',
                    '66666666666',
                    '77777777777',
                    '88888888888',
                    '99999999999',
                    '12345678909'
                ];

                var flag = false;
                for (var idx in notValids) {
                    var r = notValids[idx];

                    if (typeof(r) != "function")
                        flag = (r == value)

                    if (flag) {
                        this.markInvalid("Este CPF está na lista negra.");
                        return false;
                    }
                }

                if (!flag) {
                    var sm = 0;
                    var mod = 11;
                    var rst = 0;
                    var dgt = "";
                    var i;

                    for (i = 0; i < 9; i++) {
                        sm += (value[i] * (--mod));
                    }

                    if ((rst = sm % 11) < 2)
                        dgt += "0"
                    else
                        dgt += "" + (11 - rst);

                    sm = 0;
                    mod = 11;

                    for (i = 0; i < 10; i++) {
                        sm += (value[i] * (mod--));
                    }

                    if ((rst = sm % 11) < 2)
                        dgt += "0"
                    else
                        dgt += "" + (11 - rst);

                    result = (value.substring(9) == dgt);
                }

                if (!result) this.markInvalid("Dígito verificador inválido.");
                else this.clearInvalid();

                return result;
            },

            clean: function(value) {
                var clean = value;
                var exp = /[\.|-]/;

                while (clean.indexOf('.') > 0 || clean.indexOf('-') > 0)
                    clean = clean.replace(exp, "");

                return clean;
            },

            format: function(value) {
                var result = "";

                for (var i = 0; i < value.length; i++) {
                    if (i == 3 || i == 6) result += ".";
                    else if (i == 9) result += "-";

                    result += value[i];
                }

                return result;
            },

            onRender: function(container, position) {
                toolkit.plugins.CPFInputField.superclass.onRender.call(this, container, position);

                var tpl = new Ext.XTemplate('<input type="hidden" name="{name}" value="{value}">');
                this.input = tpl.append(
                    container,
                    {
                        name: this.name,
                        value: this.value
                    },
                    true
                );

                var inp = this.el.dom;
                var obj = this.input.dom;
                var self = this;

                inp.maxLength = 14;

                this.el.dom.onblur = function() {
                    obj.value = self.clean(inp.value);
                    self.validate();
                }

                this.el.dom.onkeypress = function(event) {
                    var result;

                    if (event.keyCode != 0) {
                        result = true;
                    }
                    else {
                        if (event.charCode >= 48 && event.charCode <= 57)
                            result = true;
                        else
                            result = false;
                    }

                    if (result && event.keyCode == 0) {
                        if (inp.value.length == 3 || inp.value.length == 7)
                            inp.value += ".";
                        else if (inp.value.length == 11)
                            inp.value += "-";
                    }

                    return result;
                }

                this.el.dom.name = "";
                if (this.value != undefined) this.value = this.format(this.value);
            }
        }
    );

    Ext.reg("cpffield", toolkit.plugins.CPFInputField);

    toolkit.plugins.FoneInputField = Ext.extend(
        Ext.form.Field,
        {
            clean: function(value) {
                var clean = value;

                clean = clean.replace("(", "");
                clean = clean.replace(")", "");
                clean = clean.replace(" ", "");
                clean = clean.replace("-", "");

                return clean;
            },

            validate: function() {
                return true;
            },

            format: function(value) {
                var result = "";

                for (var i = 0; i < value.length; i++) {
                    if (i == 0) result += "(";
                    else if (i == 2) result += ") ";
                    else if (i == 6) result += "-";

                    result += value[i];
                }

                return result;
            },

            onRender: function(container, position) {
                toolkit.plugins.FoneInputField.superclass.onRender.call(
                    this,
                    container,
                    position
                );

                if (this.value) {
                    var swap = this.value;

                    while (swap.indexOf("-") != -1)
                        swap = swap.replace(/-/, '');

                    this.value = swap;
                }

                var tpl = new Ext.XTemplate('<input type="hidden" name="{name}" value="{value}">');
                this.input = tpl.append(
                    container,
                    {
                        name: this.name,
                        value: this.value
                    },
                    true
                );

                this.el.dom.name = "";
                this.el.dom.maxLength = 14;

                var inp = this.el.dom;
                var obj = this.input.dom;
                var self = this;

                this.el.dom.onkeypress = function(event) {
                    var result;

                    if (event.keyCode != 0) {
                        result = true;
                    }
                    else {
                        if (event.charCode >= 48 && event.charCode <= 57)
                            result = true;
                        else
                            result = false;
                    }

                    if (result && event.keyCode == 0) {
                        if (inp.value.length == 0)
                            inp.value = "(";
                        else if (inp.value.length == 3)
                            inp.value += ") ";
                        else if (inp.value.length == 9)
                            inp.value += "-";
                        else if (inp.value.length == 1)
                            inp.value = "("+inp.value;
                    }

                    return result;
                };

                this.el.dom.onblur = function() {
                    obj.value = self.clean(inp.value);
                    self.validate();
                }

            },

            setValue : function(v){
                this.value = this.clean(v);
                if(this.rendered){
                    this.input.dom.value = (Ext.isEmpty(v) ? '' : this.clean(v));
                    this.el.dom.value = (Ext.isEmpty(v) ? '' : this.format(v));
                    this.validate();
                }
                return this;
            }
        }
    );

