/*
 * src: /app/root/static/js/core/DebugInformation.js
 */

/**
 *
 **/
Ext._define('core.DebugInformation', {
    extend: 'Object',

    statics: {

        toogle: function() {
            if(core.DebugInformation._state === 0) {
                core.DebugInformation._button.getEl().move(
                    'left', 350, {
                        delay: 500
                    }
                );
                core.DebugInformation._panel.getEl().move(
                    'left', 350, {
                        delay: 500
                    }
                );

                core.DebugInformation._state = 1;
            }
            else {
                core.DebugInformation._button.getEl().move(
                    'right', 350, {
                        delay: 500
                    }
                );
                core.DebugInformation._panel.getEl().move(
                    'right', 350, {
                        delay: 500
                    }
                );

                core.DebugInformation._state = 0;
            }
        },

        renderData: function(data) {
            var tpl = Ext._create('Ext.XTemplate', [
                '<div class="panel-info-body">',
                    '<tpl for="sections">',
                    '<div class="section">',
                        '<h2>{title}</h2>',
                        '<tpl for="collection">',
                            '<div class="label">{name}:</div>',
                            '<div class="value">{value}</div>',
                        '</tpl>',
                    '</div>',
                    '</tpl>',
                '</div>'
            ]);

            tpl.overwrite(
                core.DebugInformation._panel.getEl(),
                data
            );
        },

        renderTab: function() {
            core.DebugInformation._button = Ext._create('Ext.Container', {
                autoEl: 'div',
                width: 32,
                height: 48,
                renderTo: Ext.getBody(),
                cls: 'debug-info-button'
            });

            core.DebugInformation._panel = Ext._create('Ext.Container', {
                autoEl: 'div',
                width: 350,
                renderTo: Ext.getBody(),
                cls: 'debug-info-panel'
            });


            core.DebugInformation._button.getEl().on({
                click: function() {
                    core.DebugInformation.toogle();
                }
            });

            core.DebugInformation._button.render();
            core.DebugInformation._panel.render();

            core.DebugInformation._state = 1;
            setTimeout(
                function() {
                    core.DebugInformation.toogle();
                },
                3000
            );

            var task;
            task = Ext.TaskMgr.start({
                interval: 15000,
                run: function() {
                    Ext.Ajax.request({
                        url: core.callAction('DebugInformation', 'data'),
                        success: function(xhr) {
                            var rst = Ext.decode(xhr.responseText);
                            if(rst.success) core.DebugInformation.renderData(rst);
                        },
                        failure: function() {
                            Ext.TaskMgr.stop(task);
                            console.info('Debug task foi interrompida.');
                        }
                    });
                }
            });
        },

        start: function() {
            Ext.Ajax.request({
                url: core.callAction('DebugInformation', 'data'),
                success: function(xhr) {
                    var rst = Ext.decode(xhr.responseText);
                    if (rst.success && !(localStorage.getItem('hideDebugInfo') === 'on')) {
                        core.DebugInformation.renderTab();
                    };
                }
            });
        }
    }
});

/*
 * src: /app/root/static/js/auth/LinkUserServidorWindow.js
 */
/**
 * OBS: A instanciação dessa classe depende de uma configuração de banco de dados:
 *
 * Menu de Aplicativos
 *  |
 *  +-> PAINEL DE CONTROLE
 *       |
 *       +-> Eventos para o usuário
 *            |
 *            +-> Item no grid: "Associação Usuário/Servidor"
 **/
Ext._define('auth.LinkUserServidorWindow', {
    'extend': 'Ext.Window',

    'getFormPanel': function() {
        if(!this._formPanel)
            this._formPanel = new Ext.form.FormPanel({
                'border': false,
                'frame': true,
                'labelWidth': 135,
                'items': [
                    {
                        'fieldLabel': 'Sua matricula',
                        'xtype': 'textfield',
                        'name': 'matricula',
                        'allowBlank': false
                    },
                    {
                        'fieldLabel': 'Seu CPF',
                        'xtype': 'cpffield',
                        'name': 'cpf',
                        'allowBlank': false
                    },
                    {
                        'fieldLabel': 'Data de Nascimento',
                        'xtype': 'datefield',
                        'name': 'nascimento',
                        'allowBlank': false
                    },
                ]
            });

        return this._formPanel;
    },

    'submit': function() {
        var form = this.getFormPanel().getForm();

        form.waitMsgTarget = this.getEl();

        form.submit({
            'url': core.callAction('ExtLogin', 'first_access'),
            'method': 'POST',
            'waitMsg': 'Processando informações...',
            'scope': this,
            'success': function(form, action) {
                location.reload();
                this.destroy();
            },
            'failure': function(form, action) {
                var message = '';

                if(action.failureType == 'server')
                    message = action.result.msg;
                else
                    message = 'Ocorreu um erro de comunicação com servidor, tente novamente mais tarde.';

                Ext.Msg.show({
                    'title': 'Validando dados',
                    'icon': Ext.Msg.ERROR,
                    'buttons': Ext.Msg.OK,
                    'msg': message
                });
            }
        });
    },

    'constructor': function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                'title': 'Ligar Usuário ao Servidor'
            }
        );

        Ext.apply(
            cfg,
            {
                'border': false,
                'resizable': false,
                'closable': false,
                'width': 330,
                'items': [this.getFormPanel()],
                'buttons': [
                    {
                        'text': 'Validar',
                        'scope': this,
                        'handler': this.submit
                    }
                ]
            }
        );

        // this.callParent([cfg]);
        auth.LinkUserServidorWindow.superclass.constructor.call(this, cfg);
    }
});

/*
 * src: /app/root/static/js/toolkit/fields/DateTimeField.js
 */
/**
 *
 */

Ext.ns('toolkit.fields');

toolkit.fields.DateTimeField = Ext.extend(
    Ext.form.TextField,
    {
        constructor: function(cfg) {
            cfg = (cfg ? cfg : {});
            Ext.applyIf(cfg, {
                'dateFormat': Ext.form.DateField.prototype.format,
                'timeFormat': 'H:i',
                'separator': ' '
            });

            toolkit.fields.DateTimeField.superclass.constructor.call(this, cfg);

            if(this.value) this.setValue(this.value);
        },

        _getDateObjectFormat: function() {
            return this.dateFormat + this.separator + this.timeFormat;
        },

        setValue: function(newValue) {
            if(!(newValue instanceof Date))
                newValue = Date.parseDate(newValue, this._getDateObjectFormat());

            if(newValue) {
                toolkit.fields.DateTimeField.superclass.setValue.call(this, newValue.format(this._getDateObjectFormat()));

                var value = this._valueToObject();
                this.getDateField().setValue(value.date);
                this.getTimeField().setValue(value.time);
            }
        },

        _valueToObject: function(value) {
            var dt = this.getValue();

            return {
                'date': dt.format(this.dateFormat),
                'time': dt.format(this.timeFormat),
                'separator': this.separator,

                'toString': function() {
                    return this.date + this.separator + this.time;
                }
            }
        },

        getValue: function() {
            var value = toolkit.fields.DateTimeField.superclass.getValue.call(this);

            return Date.parseDate(value, this._getDateObjectFormat());
        },

        getDateField: function() {
            if(!this._datefield)
                this._datefield = new Ext.form.DateField({
                    'width': 100,
                    'submitValue': false,
                    'allowBlank': this.allowBlank,
                    'listeners': {
                        'scope': this,
                        'change': function(field, newValue, oldValue) { this._doValue() }
                    }
                });

            return this._datefield;
        },

        _doValue: function() {
            this.setValue(this.getDateField().getValue().format('d/m/Y') + ' ' + this.getTimeField().getValue());
        },

        getTimeField: function() {
            if(!this._timeField)
                this._timeField = new Ext.form.TextField({
                    'width': 60,
                    'enableKeyEvents': true,
                    'submitValue': false,
                    'allowBlank': this.allowBlank,
                    'validator': function(value) {
                        var tests = [
                            /^$/,
                            /^[0-2]$/,
                            /^([0-1][0-9]|2[0-3])$/,
                            /^([0-1][0-9]|2[0-3]):$/,
                            /^([0-1][0-9]|2[0-3]):[0-5]$/,
                            /^([0-1][0-9]|2[0-3]):[0-5][0-9]$/,
                        ];

                        var flag = false;
                        Ext.each(tests, function(t) {
                            if(t.test(value)) {
                                flag = true;
                                return false;
                            }
                        });

                        return (flag ? true : 'Horário informado é inválido.');
                    },
                    'listeners': {
                        'scope': this,
                        'keypress': function(field, evt) {
                            if(evt.charCode >= 48 && evt.charCode <= 57) {
                                var value = field.getValue();
                                if(value.length == 2)
                                    field.setValue(value + ':')
                                else if(value.length == 5)
                                    evt.stopEvent()
                            }
                            else if(evt.charCode != 0){
                                evt.stopEvent();
                                //console.debug([evt, evt.charCode, evt.keyCode]);
                            }
                        },
                        change: function(field, newValue, oldValue) { this._doValue(); }
                    }
                });

            return this._timeField;
        },

        onRender: function(container, position) {
            var p1 = new Ext.Panel({
                'items': this.getDateField(),
                'border': false
            });

            var p2 = new Ext.Panel({
                'items': this.getTimeField(),
                'border': false,
                'margins': '0 0 0 5'
            });

            var p3 = new Ext.Panel({
                'width': 0
            });

            var pn = new Ext.Panel({
                'layout': 'hbox',
                'renderTo': container,
                'items': [p1, p2, p3],
                'border': false,
                'width': 200
            });

            this.inputType = 'hidden'
            toolkit.fields.DateTimeField.superclass.onRender.call(this, p3.body);
        }
    }
);

toolkit.fields.DateTimeExtendedField = Ext.extend(
    toolkit.fields.DateTimeField,
    {
        _getDateObjectFormat: function() {
            var _format = '';
            if(this.getDateField())
                _format = this.dateFormat + this.separator;
            _format = _format + this.timeFormat;
            return _format;
        },

        setValue: function(newValue) {
            if(!(newValue instanceof Date)){
                if(this.getDateField())
                    newValue = Date.parseDate(newValue, this._getDateObjectFormat());
            }
            if(newValue) {
                if(this.getDateField())
                    toolkit.fields.DateTimeField.superclass.setValue.call(this, newValue.format(this._getDateObjectFormat()));
                else{
                    if(newValue.indexOf(':') == -1)
                        newValue = newValue.slice(0, 2) + ':' + newValue.slice(2, 4);
                    toolkit.fields.DateTimeField.superclass.setValue.call(this, newValue);
                }

                var value = this._valueToObject();
                if(this.getDateField())
                    this.getDateField().setValue(value.date);
                this.getTimeField().setValue(value.time);
            }
        },

        _valueToObject: function(value) {
            var dt = this.getValue();
            return {
                date: this.getDateField() ? dt.format(this.dateFormat) : '',
                time: this.getDateField() ? dt.format(this.timeFormat) : dt,
                separator: this.separator,
                toString: function() {
                    var value = '';
                    if(this.date != '')
                        value = this.date + this.separator;
                    value = value + this.time;
                    return value;
                }
            }
        },

        getValue: function() {
            var value = toolkit.fields.DateTimeField.superclass.getValue.call(this);
            var dt = value;
            if(this.getDateField())
                dt = Date.parseDate(value, this._getDateObjectFormat());
            return dt;
        },

        getDateField: function() {
            return undefined;
        },

        _doValue: function() {
            if(this.getDateField())
                this.setValue(this.getDateField().getValue().format('d/m/Y') + ' ' + this.getTimeField().getValue());
            else
                this.setValue(this.getTimeField().getValue());
        },

        getTimeField: function() {
            if(!this._timeField)
                this._timeField = new Ext.form.TextField({
                    width: 60,
                    enableKeyEvents: true,
                    submitValue: false,
                    allowBlank: this.allowBlank,
                    validator: function(value) {
                        var tests = [
                            /^$/,
                            /^[0-2]$/,
                            /^([0-1][0-9]|2[0-3])$/,
                            /^([0-1][0-9]|2[0-3]):$/,
                            /^([0-1][0-9]|2[0-3]):[0-5]$/,
                            /^([0-1][0-9]|2[0-3]):[0-5][0-9]$/,
                        ];

                        var flag = false;
                        Ext.each(tests, function(t) {
                            if(t.test(value)) {
                                flag = true;
                                return false;
                            }
                        });

                        return (flag ? true : 'Horário informado é inválido.');
                    },
                    listeners: {
                        scope: this,
                        keyup: function(field, evt) {
                            var el = field.getEl();
                            var selectionStart = el.dom.selectionStart;
                            var selectionEnd = el.dom.selectionEnd;
                            var oldValue = field.getValue();

                            valueDigits = oldValue.replace(':', '');
                            if(oldValue.length == 2 && !/\D/.test(oldValue)){
                                var newValue = oldValue + ':';
                                field.setValue(newValue);
                                field.fireEvent('change', [field, newValue, oldValue]);
                            }else if(valueDigits.length > 4 && !/\D/.test(valueDigits)){
                                var newValue = valueDigits.slice(0, 2) + ':' + valueDigits.slice(2, valueDigits.length -1);
                                field.setValue(newValue);
                                field.fireEvent('change', [field, newValue, oldValue]);
                            }

                            if(oldValue.length >=5){
                                if(selectionStart == 3){
                                    selectionStart = 4;
                                    selectionEnd = 4;
                                }
                                if(!this._prevent){
                                    el.dom.selectionStart = selectionStart;
                                    el.dom.selectionEnd = selectionEnd;
                                }
                            }
                        },
                        keypress: function(field, evt) {
                            if(evt.charCode >= 48 && evt.charCode <= 57)
                                this._prevent = false;
                            else{
                                this._prevent = true;
                                evt.stopEvent();
                            }
                        },
                        change: function(field, newValue, oldValue) {this._doValue(); }
                    }
                });

            return this._timeField;
        }
    }
);

Ext.reg('tk-datetimefield', toolkit.fields.DateTimeField);
Ext.reg('tk-datetimeextendedfield', toolkit.fields.DateTimeExtendedField);
/*
 * src: /app/root/static/js/toolkit/fields/AutoCompleteField.js
 */
/**
 *
 **/

Ext.ns('toolkit.plugins');

toolkit.plugins.AutoCompleteField = Ext.extend(
    Ext.form.ComboBox,
    {
        setReadOnly: function(readOnly) {
            if(readOnly)
                this.button.disable();
            else
                this.button.enable();

            toolkit.plugins.AutoCompleteField2.superclass.setReadOnly.call(this, readOnly);
        },

        disable: function() {
            this.button.disable();
            toolkit.plugins.AutoCompleteField2.superclass.disable.call(this);
        },

        enable: function() {
            this.button.enable();
            toolkit.plugins.AutoCompleteField2.superclass.enable.call(this);
        },

        clearValue: function() {
            toolkit.plugins.AutoCompleteField2.superclass.clearValue.call(this);
            this.fireEvent('clear', this);
            this.focus();
        },

        setValue: function(value) {
            value = (value != '' ? value : null);

            if(value && (value != '' || value != null) && !(this.getStore().find(this.valueField, value) >= 0)) {
                this.getStore().baseParams.keyword = null;

                this.getStore().load({
                    params: { pk: value },
                    scope: this,
                    callback: function() {
                        var index = this.getStore().find(this.valueField, value);
                        if(index >= 0) {
                            var record = this.getStore().getAt(index);
                            record != undefined && this.fireEvent('select', this, record, index);
                            toolkit.plugins.AutoCompleteField2.superclass.setValue.call(this, value);
                            this.clearInvalid();
                        }
                        else {
                            this.markInvalid('Selecione um item da lista.');
                        }
                    }
                });
            }
            else if(value && value == '') {
                console.debug('do clear value');
            }
            else {
                toolkit.plugins.AutoCompleteField2.superclass.setValue.call(this, value);
            }
        },

        constructor: function(cf) {
            if(cf.crudController && !cf.father) {
                cf.store = new Ext.data.JsonStore({
                    url: toolkit.util.Normalize.controller_action(cf.crudController, cf.queryAction),
                    fields: [
                        cf.valueField,
                        cf.displayField,
                        'controller'
                    ],
                    root: 'result'
                });
            }
            else if(cf.father) {
                //-- Correção para manter a compatibilidade com a versão anterior.
                cf.store = new Ext.data.JsonStore({
                    url: toolkit.util.Normalize.controller_action(cf.father, 'autocomplete', [cf.model]),
                    fields: [
                        cf.valueField,
                        cf.displayField,
                        'controller'
                    ],
                    root: 'result'
                });
                cf.queryParam = 'query';
                //-- Correção para manter a compatibilidade com a versão anterior.
            }
            else if(cf.genericCrud) {
                cf.store = new Ext.data.JsonStore({
                    url: toolkit.util.Normalize.controller_action('ExtCrudGeneric', 'query'),
                    fields: [
                        cf.valueField,
                        cf.displayField,
                        'controller'
                    ],
                    root: 'result',
                    baseParams: {
                        model_app_label: cf.model.app_label,
                        model_name: cf.model.name
                    }
                });
            };

            if(cf.defaultParams)
                Ext.apply(
                    cf.store.baseParams,
                    cf.defaultParams
                )

            cf.minChars = 3;

            Ext.applyIf(cf, {
                'resizable': true,
                'stateful': true,
                'stateId': 'stateful-' + this.controller + '-' + this.hiddenName
            });

            toolkit.plugins.AutoCompleteField2.superclass.constructor.call(this, cf);
            this.addEvents('clear');
        },

        _select: function() {
            var frm = new toolkit.plugins.AutocompleteSelectWindow(this);
            frm.show();
        },

        _edit: function() {
            if(this.getValue() != '') {
                var scope = {
                    father: {
                        controller: this.crudController,
                        reload_grid: function() {}
                    },
                    form: false
                };
                if(this.subcontrollers) {
                    var store = this.getStore();
                    scope.father.controller = store.getAt(store.find('pk', this.value)).get('controller');
                }
                scope.form = new toolkit.widget.ExtCrudForm(scope.father, 2, this.getValue());
                scope.form.action_commit_ex = scope.form.action_commit;
                scope.form.el = this;
                scope.form.action_commit = function(type) {
                    var r = this.action_commit_ex(type);
                    this.el.setValue(r.cid);
                    return r;
                };
                scope.form.show();
            }
            else alert('Nenhum item foi selecionado para edição.')
        },

        _add: function(specialized_controller) {
            var scope = {
                father: {
                    controller: this.crudController,
                    reload_grid: function() {}
                },
                form: false
            };

            if(specialized_controller)
                scope.father.controller = specialized_controller;

            scope.form = new toolkit.widget.ExtCrudForm(scope.father, 1);
            scope.form.action_commit_ex = scope.form.action_commit;
            scope.form.el = this;

            scope.form.action_commit = function(type) {
                var r = this.action_commit_ex(type);
                this.el.setValue(r.cid);
                return r;
            };

            scope.form.show();
        },

        onRender: function(container, position) {
            var child = new Ext.Panel({
                border: false
            });

            var menu = [
                {
                    text: 'Modificar',
                    icon: "/" + global.Context + '/static/images/edit.png',
                    scope: this,
                    handler: function() { this.clearValue(); }
                }
            ];

            if(this.conf) {
                (this.conf.canAdd || this.conf.canEdit) && menu.push('-');
                if(this.conf.canAdd && !this.subcontrollers)
                    menu.push({
                        text: this.conf.addLabel ? this.conf.addLabel : 'Adicionar ...',
                        icon: this.conf.addIcon ? this.conf.addIcon : '/' + global.Context + '/static/images/add.png',
                        scope: this,
                        handler: function() { this._add() }
                    });
                else if(this.conf.canAdd && this.subcontrollers) {
                    var submenu = [];

                    Ext.each(
                        this.subcontrollers,
                        function(record) {
                            submenu.push({
                                text: record.title,
                                icon: record.icon,
                                handler: function() { this._add(record.controller) },
                                scope: this
                            })
                        },
                        this
                    )

                    menu.push({
                        text: this.conf.addLabel ? this.conf.addLabel : 'Adicionar ...',
                        icon: this.conf.addIcon ? this.conf.addIcon : '/' + global.Context + '/static/images/add.png',
                        menu: submenu
                    });
                }

                if(this.conf.canEdit)
                    menu.push({
                        text: this.conf.editLabel ? this.conf.editLabel : 'Visualizar Registro ...',
                        icon: this.conf.editIcon ? this.conf.editIcon : '/' + global.Context + '/static/engine/images/icons/athenas-0036.png',
                        scope: this,
                        handler: this._edit
                    });
            }

            if(!this.genericCrud) {
                menu.push('-');
                menu.push({
                    text: 'Selecionar...',
                    scope: this,
                    handler: this._select,
                    scope: this,
                    iconCls: true,
                    icon: "/" + global.Context + "/static/images/document-export.png"
                });
            }

            var bnt = new Ext.Button({
                iconCls: true,
                style: 'margin-left: 5pt',
                icon: "/" + global.Context + "/static/images/view-sort-ascending.png",
                menu: menu
            });

            var panel = new Ext.Panel({
                layout: 'column',
                border: false,
                renderTo: container,
                cls: (this.toolbarInside ? 'toolbar-inside' : ''),
                items: [child, bnt]
            });

            this.button = bnt;

            this.width = this.width - (bnt.getBox().width + 5);

            toolkit.plugins.AutoCompleteField2.superclass.onRender.call(this, child.body);
        }
    }
);

